 60	  const [binding] = await db
 61	    .select()
 62	    .from(workspaceIdentity)
 63	    .where(eq(workspaceIdentity.googleSubject, subject));
 64	  if (!binding && !allowInitialBinding) throw new WorkspaceUnavailable(true);
 65	
 66	  const url = new URL(
 67	    `https://admin.googleapis.com/admin/directory/v1/users/${encodeURIComponent(binding?.directoryId ?? identity.email)}`,
 68	  );
 69	  url.searchParams.set("viewType", "domain_public");
 70	  url.searchParams.set("fields", "id,primaryEmail,name(fullName)");
 71	  const profile = profileSchema.parse(await googleGet(url.toString(), accessToken));
 72	  if (
 73	    profile.primaryEmail.toLowerCase() !== identity.email.toLowerCase() ||
 74	    (binding && profile.id !== binding.directoryId)
 75	  )
 76	    throw new WorkspaceUnavailable(true);
 77	
 78	  if (!binding) {
 79	    await db
 80	      .insert(workspaceIdentity)
 81	      .values({ googleSubject: subject, directoryId: profile.id })
 82	      .onConflictDoNothing();
 83	    const [saved] = await db
 84	      .select()
 85	      .from(workspaceIdentity)
 86	      .where(eq(workspaceIdentity.googleSubject, subject));
 87	    if (saved?.directoryId !== profile.id) throw new WorkspaceUnavailable(true);
 88	  }
 89	  return profile;
 90	}
