 92	export async function hasReviewerRole(accessToken: string, directoryId: string, roleId: string) {
 93	  const url = new URL(
 94	    "https://admin.googleapis.com/admin/directory/v1/customer/my_customer/roleassignments",
 95	  );
 96	  url.searchParams.set("userKey", directoryId);
 97	  url.searchParams.set("includeIndirectRoleAssignments", "true");
 98	  const response = await fetch(url, {
 99	    headers: { Authorization: `Bearer ${accessToken}` },
100	    cache: "no-store",
101	    signal: AbortSignal.timeout(10_000),
102	  });
103	  if (response.status === 403) return false;
104	  if (!response.ok) throw new WorkspaceUnavailable(response.status === 401);
105	  return (
106	    roleAssignmentsSchema
107	      .parse(await response.json())
108	      .items?.some((item) => item.roleId === roleId) ?? false
109	  );
110	}

